  "buichi-saito": {
    "image": "",
    "imageAlt": "",
    "bio": "Buichi Saitō was a Japanese film director and screenwriter born in 1925. After graduating from Waseda University, he joined Shochiku and worked as an assistant to directors including Yasujirō Ozu and Kōzaburō Yoshimura. He later moved to Nikkatsu, where he made his directorial debut in the 1950s. Saitō became closely associated with the studio's popular action and youth films. His best-known work includes the Wataridori series and films featuring stars such as Akira Kobayashi and Sayuri Yoshinaga. His career linked classical studio training with the faster, more commercially driven style of postwar Japanese popular cinema.",
    "credit": ""
  },
