  "susan-streitfeld": {
    "image": "",
    "imageAlt": "",
    "bio": "Susan Streitfeld is an American director, screenwriter, and visual artist. She studied painting at Syracuse University before completing film training at New York University. Her feature directing debut was Female Perversions, adapted from psychoanalyst Louise J. Kaplan's book. Streitfeld co-wrote the screenplay, and Tilda Swinton starred in her first American film role. The film uses heightened imagery and dream sequences to explore ambition, sexuality, family pressure, and the demand for female perfection. Its later restoration and theatrical revival renewed attention to Streitfeld's distinctive feminist perspective.",
    "credit": ""
  },
